var_const_consistency.srd:
FOR EACH symbol: IF symbol.is_constant AND symbol.definition_count > 1 THEN REPORT violation 'constant_redefined';
FOR EACH symbol: IF symbol.is_constant AND symbol.is_variable THEN REPORT violation 'constant_variable_confusion';
FOR EACH symbol: IF symbol.is_variable AND symbol.is_constant THEN REPORT violation 'variable_constant_confusion';
FOR EACH symbol: IF symbol.definition_count > 1 AND symbol.unit is_not consistent THEN REPORT violation 'unit_inconsistency';
FOR EACH symbol: IF symbol.definition_count > 1 AND symbol.dimension is_not consistent THEN REPORT violation 'dimension_inconsistency';
FOR EACH graph: IF graph.has_cycles THEN REPORT violation 'symbol_overloading_ambiguity';
